import{_ as l,l as r,o as e,c as o,v as t,p as d,x as i,d as s,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"财报滞后与可用日期","description":"","frontmatter":{"title":"财报滞后与可用日期","date":"2026-09-10T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/filing-lag-available-date.md","filePath":"quant/filing-lag-available-date.md","lastUpdated":1789023840000}'),E={name:"quant/filing-lag-available-date.md"};function A(c,a,u,m,_,f){const n=r("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="财报滞后与可用日期" tabindex="-1">财报滞后与可用日期 <a class="header-anchor" href="#财报滞后与可用日期" aria-label="Permalink to &quot;财报滞后与可用日期&quot;">​</a></h1><div class="epigraph"><p>报告期在 12 月 31 日结束，并不等于 1 月 2 日就能交易这笔数字；可用日期是市场第一次公开读到报表的日历日。</p><footer>—— 据 Fama and French, Journal of Financial Economics, 1993 因子构造说明；SEC 申报期限与 Compustat 公告日字段整理</footer></div><p>上一课<a href="/quant/pit-fundamentals">Point-in-time 基本面</a>把 as-of 写成记录级约束。仍缺日历：公告日从哪来、法定截止不等于实际披露、季报与年报滞后不同。本课把 PIT 收成可执行的<strong>可用日期</strong>。下一课才处理谁从样本里消失。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>PIT 说「只用当时存在的版本」，但版本何时存在？用 period_end 会提前一到四个月；用 vendor 的 last_updated 会把后来修订的时间戳污染历史；用法定申报截止日（美国 10-K 的 60/75/90 天档）会把提前披露的公司推迟、把逾期公司提前。缺口是给每条记录一个<strong>市场可读取日</strong> \\(d^{avail}\\)，信号日 \\(t\\) 只读 \\(d^{avail}\\le t\\)。</p><p>Fama–French 用 \\(t\\) 年 6 月的市值配 \\(t-1\\) 财年账面，把滞后写成组合日历上的粗规则。事件研究与日频因子没有这份奢侈：同一周里，有的公司已发 8-K，有的还在静默期。没有可用日期，截面排序在比较「已披露」与「尚未披露」的公司。</p><h3 id="公告日不是财报截止日" tabindex="-1">公告日不是财报截止日 <a class="header-anchor" href="#公告日不是财报截止日" aria-label="Permalink to &quot;公告日不是财报截止日&quot;">​</a></h3><p>fiscal period end 是会计期间的右端点。filing date / earnings announcement date 才是信息进入价格的候选时点。两者相差的「滞后」本身可交易，但本课先当数据约束，不当 alpha。把截止日当公告日，等于假设所有公司在法定最后一天同时披露——这与事实相反，也与后课公告窗口研究直接冲突。</p><p><span class="marginnote">IBES 与 Compustat 的公告日字段会对不齐。事件研究要用更干净的公告时点；截面因子至少要一个不晚于真实披露的截断日。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对每条基本面记录存 \\(d^{avail}\\)。优先顺序：交易所/监管公告时间戳；其次 vendor 的 rdq / filedate；再次用法定截止日作上界并加缓冲。周末与休市：可用日期落到下一交易日，避免把周五盘后公告写进周五收盘信号。季报滞后短、年报滞后长，同一公司不要套一个全局 \\(k\\)。</p><p>Fama–French 的六月规则可以保留为价值因子的稳健默认，但应计、盈利、惊喜类日频信号必须用记录级 \\(d^{avail}\\)。后课<a href="/quant/earnings-announcement-window">财报公告窗口</a>会把 \\(d^{avail}\\) 当成事件日；本课只要求它先存在、且不前视。</p>',12)),(e(),d(h,null,{default:i(()=>[p(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20END%5B%22%E6%8A%A5%E5%91%8A%E6%9C%9F%E7%BB%93%E6%9D%9F%22%5D%20--%3E%20LAG%5B%22%E6%8A%AB%E9%9C%B2%E6%BB%9E%E5%90%8E%22%5D%0A%20%20LAG%20--%3E%20AVAIL%5B%22%E5%8F%AF%E7%94%A8%E6%97%A5%E6%9C%9F%22%5D%0A%20%20AVAIL%20--%3E%20SIG%5B%22%E4%BF%A1%E5%8F%B7%E6%97%A5%E5%8F%AF%E8%AF%BB%E5%8F%96%22%5D%0A%20%20END%20-.-%3E%7C%22%E8%AF%AF%E7%94%A8%E6%88%AA%E6%AD%A2%E6%97%A5%22%7C%20EARLY%5B%22%E6%8F%90%E5%89%8D%E4%BA%A4%E6%98%93%E5%B9%BB%E8%A7%89%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>滞后制造两种回测偏差。一种是抢跑：用尚未公开的季报算当季因子。一种是错位比较：已披露公司与未披露公司排在同一截面，排序混进了「披露状态」。可用日期把公司从「有数字」集合里按时点放进、放出。静默期、业绩预告、修正公告是同一机制的多次到达：每次到达更新 \\(d^{avail}\\) 与当时版本，而不是覆盖历史。</p><p><span class="marginnote">盘后公告归属哪一个交易日，要与后课窗口研究的约定一致。本课只要求：回测里写死一条规则，并与价格复权日历对齐。</span></p><p>盘后与盘前要写进同一条规则，并与价格日历的时区一致。美股常用「16:00 之后算下一交易日」；A 股公告常在晚间，同样归次日。事件研究与截面因子必须共用这条归属，否则同一份财报在两个管道里是两个事件日。法定截止日只作缺失公告日时的上界，且应加缓冲，切勿把上界当成真实披露。滞后分布本身可以做研究，但本课先当约束，不当 alpha。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不比较各国法定天数表，不写监管法条。EDGAR 与新闻社的分钟级时差交给事件研究，不在此做成高频。下一课<a href="/quant/survivorship-delist">幸存者与退市</a>处理样本进出，不处理披露时钟。后课默认：每个基本面字段带可用日期；六月规则只是年频价值因子的特例。</p><p>后课公告窗口、惊喜、事件策略全部复用本课的 \\(d^{avail}\\) 归属规则；中途改盘后定义等于改写历史事件日。缺失公告日时用法定截止加缓冲，并在结果里报告缺失比例。不要用 vendor 最后更新时间替代公告日，那会把修订写进第一次披露。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PIT 约束版本；本课给版本一个可读取的日历日。</li><li>报告期结束、法定截止、公告日是三个不同时点。</li><li>固定月数滞后是代理；记录级可用日期才可进日频信号。</li><li>Fama–French 六月规则是粗滞后，不是 PIT 的替代定义。</li><li>公告窗口研究将复用本课的可用日期当事件日。</li><li>出处：Fama–French (1993) 构造说明；SEC 申报期限；Compustat 公告日字段。</li></ul>',9))])}const q=l(E,[["render",A]]);export{B as __pageData,q as default};
